Object.assign(window.TEM8_DICTIONARY, {"employ":{"media":{"uk":"media/uk/employ__gb_1.mp3","us":"media/us/employ__us_1.mp3"},"oxford":{"phon":"ɪmˈplɔɪ","pos":"verb","senses":[{"en":"to give somebody a job to do for payment","cn":"雇用","lab":"British English","ex":{"en":"How many people does the company employ?","cn":"这家公司雇用了多少人？"}},{"en":"to use something such as a skill, method, etc. for a particular purpose","cn":"应用；运用；使用","lab":"formal","ex":{"en":"to employ a technique/strategy/tactic","cn":"采用技术／战略／策略"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"雇用","en":"If a person or company employs you, they pay you to work for them.","ex":{"en":"The company employs 18 staff","cn":"公司雇用了18名员工。"}},{"pos":"VERB 动词","cn":"使用;采用","en":"If you employ certain methods, materials, or expressions, you use them.","ex":{"en":"The tactics the police are now to employ are definitely uncompromising.","cn":"警方目前即将采取的策略明显很强硬。"}},{"pos":"VERB 动词","cn":"利用，花费（时间）","en":"If your time is employed in doing something, you are using the time you have to do that thing.","ex":{"en":"Your time could be usefully employed in attending to professional matters","cn":"你可以有效地利用时间处理一些专业问题。"}},{"pos":"PHRASE 短语","cn":"受雇于","en":"If you are in the employ of someone or something, you work for them.","ex":{"en":"Others hinted that he was in the employ of the KGB","cn":"其他人暗示他受雇于克格勃。"}}]},"examples":[{"en":"He criticized the repressive methods employed by the country's government.","cn":"他指责了这个国家政府采取的镇压手段。"},{"en":"She was employed in making a list of all the jobs to be done.","cn":"她忙着把要做的所有工作列一个清单。"}]},"empty":{"media":{"uk":"media/uk/empty__gb_1.mp3","us":"media/us/empty__us_1.mp3"},"oxford":{"phon":"ˈempti","pos":"adjective","senses":[{"en":"with no people or things inside","cn":"空的","lab":"formal","ex":{"en":"an empty box/glass/bottle","cn":"空盒；空杯；空瓶"}},{"en":"with no meaning; not meaning what is said","cn":"空洞的；说话不算数的；无诚意的","g":"[usually before noun]","ex":{"en":"empty words","cn":"空话"}},{"en":"unhappy because life does not seem to have a purpose, usually after something sad has happened","cn":"空虚的；无意义的；无目的的","ex":{"en":"Three months after his death, she still felt empty.","cn":"他死后三个月她仍然感到心里空落落的。"}},{"en":"without a quality that you would expect to be there","cn":"没有；缺乏；无","ex":{"en":"words that were empty of meaning","cn":"无意义的话"}},{"en":"to remove everything that is in a container, etc.","cn":"倒空；腾空；掏空","g":"[transitive]","lab":"figurative","ex":{"en":"She emptied the bins, washed the glasses and went to bed.","cn":"她倒掉垃圾，洗完杯子就上床睡觉了。"},"pos":"verb"},{"en":"to become empty","cn":"变空","g":"[intransitive]","ex":{"en":"The streets soon emptied when the rain started.","cn":"雨下起来，街上很快便空无一人了。"},"pos":"verb"},{"en":"to take out the contents of something and put them somewhere else","cn":"把…移出，把…腾出（置于别处）","g":"[transitive]","ex":{"en":"He stepped outside to empty the trash.","cn":"他走出去倒垃圾。"},"pos":"verb"},{"en":"to make sure that everyone leaves a room, building, etc.","cn":"（把…）撤出，撤离；撤空","g":"[transitive]","ex":{"en":"Police had instructions to empty the building because of a bomb threat.","cn":"由于炸弹的威胁，警方奉命将所有人撤离这栋大楼。"},"pos":"verb"},{"en":"to flow or move out from one place to another","cn":"流入；涌进","g":"[intransitive]","ex":{"en":"The Rhine empties into the North Sea.","cn":"莱茵河流入北海。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"空的","en":"An empty place, vehicle, or container is one that has no people or things in it.","ex":{"en":"The room was bare and empty.","cn":"房间空荡荡的。"}},{"pos":"ADJ 形容词","cn":"(威胁、关系等)空洞的，无意义的，无效的","en":"An empty gesture, threat, or relationship has no real value or meaning.","ex":{"en":"His father threatened to throw him out, but he knew it was an empty threat.","cn":"他父亲威胁要把他赶出去，但他知道那只不过是吓吓他罢了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(生活或某段时间)空虚的，枯燥无味的","en":"If you describe a person's life or a period of time as empty, you mean that nothing interesting or valuable happens in it.","ex":{"en":"My life was very hectic but empty before I met him.","cn":"在遇到他之前，我的生活非常繁忙却很空虚。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（感觉）空虚的，无力的","en":"If you feel empty, you feel unhappy and have no energy, usually because you are very tired or have just experienced something upsetting.","ex":{"en":"I felt empty and hollow; defeated","cn":"我感觉空虚无聊，充满挫败感。"}},{"pos":"VERB 动词","cn":"清空;把…倒空","en":"If you empty a container, or empty something out of it, you remove its contents, especially by tipping it up.","ex":{"en":"I emptied the ashtray","cn":"我把烟灰缸倒空了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（房间、场地等）变空;清空","en":"If someone empties a room or place, or if it empties, everyone that is in it goes away.","ex":{"en":"The stadium emptied at the end of the first day of athletics.","cn":"首日比赛结束后，体育场空无一人。"}},{"pos":"VERB 动词","cn":"（河流或运河）流入，注入","en":"A river or canal that empties into a lake, river, or sea flows into it.","ex":{"en":"The Washougal empties into the Columbia River near Portland.","cn":"沃舒格尔河在波特兰附近注入哥伦比亚河。"}},{"pos":"N-COUNT 可数名词","cn":"空瓶；空容器","en":"Empties are bottles or containers which no longer have anything in them."}]},"examples":[{"en":"I emptied out my pockets but could not find my keys.","cn":"我把口袋里的东西都掏了出来，仍然找不到我的钥匙。"},{"en":"He emptied the ashtrays, washed the glasses and went to bed.","cn":"他倒掉烟灰缸里的灰，洗完杯子就上床睡觉了。"}]},"embarrassment":{"oxford":{"phon":"ɪmˈbærəsmənt","pos":"noun","senses":[{"en":"shy, uncomfortable or guilty feelings; a feeling of being embarrassed","cn":"害羞；窘迫；愧疚；难堪","g":"[uncountable]","ex":{"en":"I nearly died of embarrassment when he said that.","cn":"他说那话差点儿把我给难堪死了。"}},{"en":"a situation that causes problems for somebody","cn":"使人为难的处境；困境","g":"[countable]","ex":{"en":"Her resignation will be a severe embarrassment to the party.","cn":"她的辞职将使党处于极度的困境。"}},{"en":"a person who causes problems for another person or other people and makes them feel embarrassed","cn":"令人为难（或难堪、尴尬）的人","g":"[countable]","ex":{"en":"Poor Lucy! He's such an embarrassment to her.","cn":"可怜的露西！他对她来说真是一个耻辱。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"尴尬;难堪;窘迫","en":"Embarrassment is the feeling you have when you are embarrassed.","ex":{"en":"It is a source of embarrassment to Londoners that the standard of pubs is so low","cn":"酒馆水准之低让伦敦人觉得颜面尽失。"}},{"pos":"N-COUNT 可数名词","cn":"麻烦;难题;难堪的事","en":"An embarrassment is an action, event, or situation which causes problems for a politician, political party, government, or other public group.","ex":{"en":"The poverty figures were undoubtedly an embarrassment to the president.","cn":"贫困数字毫无疑问让总统非常难堪。"}},{"pos":"N-SING 单数名词","cn":"使人为难(或难堪)的人","en":"If you refer to a person as an embarrassment, you mean that you disapprove of them but cannot avoid your connection with them.","ex":{"en":"You have been an embarrassment to us from the day Douglas married you.","cn":"从道格拉斯娶你那天起，你就让我们非常难堪。"}},{"pos":"PHRASE 短语","cn":"好东西太多而成了问题","en":"If you say that someone has an embarrassment of riches, you mean that they have so many good things that these things are a problem.","ex":{"en":"The art gallery's problem is an embarrassment of riches, with nowhere to put most of them.","cn":"那家美术馆的问题是好作品太多，大多数作品无处陈放。"}}]},"media":{"uk":"media/uk/embarrassment__gb_1.mp3","us":"media/us/embarrassment__us_1.mp3"},"examples":[{"en":"Much to her embarrassment she realized that everybody had been listening to her singing.","cn":"她意识到大家一直在听她唱歌，感到很不好意思。"},{"en":"I'm glad you offered — it saved me the embarrassment of having to ask.","cn":"你愿意帮忙我很高兴，省得我厚着脸皮来问你。"}]},"emphasis":{"media":{"uk":"media/uk/emphasis__gb_1.mp3","us":"media/us/emphasis__us_1.mp3"},"oxford":{"phon":"ˈemfəsɪs","pos":"noun","senses":[{"en":"special importance that is given to something","cn":"强调；重视；重要性","ex":{"en":"Since the elections there has been a greater emphasis on education.","cn":"自选举以来，教育更加受到重视。"}},{"en":"the extra force given to a word or phrase when spoken, especially in order to show that it is important; a way of writing a word (for example drawing a line below it) to show that it is important","cn":"（对某个词或短语的）强调，加重语气，重读","ex":{"en":"You're placing the emphasis on the wrong syllable.","cn":"你把重音放错音节了。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"重点;强调","en":"Emphasis is special or extra importance that is given to an activity or to a part or aspect of something.","ex":{"en":"Too much emphasis is placed on research","cn":"过分强调研究的重要性。"}},{"pos":"N-VAR 可变名词","cn":"（对音节、单词或短语的）强调，重读","en":"Emphasis is extra force that you put on a syllable, word, or phrase when you are speaking in order to make it seem more important.","ex":{"en":"'I might have known it!' Miss Burnett said with emphasis","cn":"“我早该料到了！”伯内特小姐加重语气说。"}}]},"examples":[{"en":"‘I can assure you,’ she added with emphasis, ‘the figures are correct.’ “","cn":"我可以向你保证，”她加重语气补充道，“这些数字是正确的。”"},{"en":"The examples we will look at have quite different emphases.","cn":"我们将要观察的例子所强调的重点很不相同。"}]},"embrace":{"media":{"uk":"media/uk/embrace__gb_1.mp3","us":"media/us/embrace__us_1.mp3"},"oxford":{"phon":"ɪmˈbreɪs","pos":"noun","senses":[{"en":"an act of putting your arms around somebody as a sign of love or friendship","cn":"拥抱某人的行为，作为爱或友谊的象征","g":"[countable]","ex":{"en":"He held her in a warm embrace.","cn":"他热情地拥抱她。"}},{"en":"the act of accepting an idea, a proposal, a set of beliefs, etc, especially when it is done with enthusiasm","cn":"接受一个想法、提议、一系列信念等的行为，尤其是当它是以热情的方式进行的","g":"[uncountable]","ex":{"en":"the country’s eager embrace of modern technology","cn":"国家对现代技术的热情接受"}},{"en":"to put your arms around somebody as a sign of love or friendship","cn":"抱；拥抱","g":"[intransitive, transitive]","ex":{"en":"They embraced and promised to keep in touch.","cn":"他们互相拥抱，许诺将保持联系。"},"pos":"verb"},{"en":"to accept an idea, a proposal, a set of beliefs, etc., especially when it is done with enthusiasm","cn":"欣然接受，乐意采纳（思想、建议等）；信奉（宗教、信仰等）","g":"[transitive]","ex":{"en":"to embrace democracy/feminism/Islam","cn":"信奉民主／女权主义／伊斯兰教"},"pos":"verb"},{"en":"to include something","cn":"包括；包含","g":"[transitive]","ex":{"en":"The talks embraced a wide range of issues.","cn":"这些谈话涉及的问题非常广泛。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"抱；拥抱","en":"If you embrace someone, you put your arms around them and hold them tightly, usually in order to show your love or affection for them. You can also say that two people embrace .","ex":{"en":"Penelope came forward and embraced her sister","cn":"佩内洛普走上前拥抱了她妹妹。"}},{"pos":"VERB 动词","cn":"欣然接受，支持（变革、政治体制、观点等）","en":"If you embrace a change, political system, or idea, you accept it and start supporting it or believing in it.","ex":{"en":"He embraces the new information age","cn":"他迎接新的信息时代的到来。"}},{"pos":"VERB 动词","cn":"包括;接纳","en":"If something embraces a group of people, things, or ideas, it includes them in a larger group or category.","ex":{"en":"...a theory that would embrace the whole field of human endeavour.","cn":"将囊括人类活动的各个领域的理论"}}]},"examples":[{"en":"They embraced and promised to keep in touch.","cn":"他们互相拥抱，许诺将保持联系。"},{"en":"There were tears and embraces as they said goodbye.","cn":"他们分别时又是流泪，又是拥抱。"}]},"emperor":{"media":{"uk":"media/uk/emperor__gb_1.mp3","us":"media/us/emperor__us_1.mp3"},"oxford":{"phon":"ˈempərə(r)","pos":"noun","senses":[{"en":"the ruler of an empire","cn":"皇帝","ex":{"en":"the Roman emperors","cn":"古罗马皇帝"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"皇帝;君主","en":"An emperor is a man who rules an empire or is the head of state in an empire."}]},"examples":[{"en":"Soon investors will realize that the emperor has no clothes and there will be a big sell-off in stocks.","cn":"投资者很快会了解事实真相，股票将被大肆抛售。"},{"en":"the Roman emperors","cn":"古罗马皇帝"}]},"emigrate":{"media":{"uk":"media/uk/emigrate__gb_1.mp3","us":"media/us/emigrate__us_1.mp3"},"oxford":{"phon":"ˈemɪɡreɪt","pos":"verb","senses":[{"en":"to leave your own country to go and live permanently in another country","cn":"移居国外；移民","ex":{"en":"The family left Czechoslovakia in 1968 and emigrated to America.","cn":"1968 年，一家人离开捷克斯洛伐克移民到美国。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"移居国外;移民","en":"If you emigrate, you leave your own country to live in another country.","ex":{"en":"He emigrated to Belgium","cn":"他移民到比利时。"}}]},"examples":[{"en":"the mass emigration of Jews from Eastern Europe","cn":"犹太人从东欧往其他地区的大批移居"},{"en":"He emigrated to Australia as a young man.","cn":"他年轻时移居澳大利亚。"}]},"empirical":{"media":{"uk":"media/uk/empirical__gb_1.mp3","us":"media/us/empirical__us_1.mp3"},"oxford":{"phon":"ɪmˈpɪrɪkl","pos":"adjective","senses":[{"en":"based on experiments or experience rather than ideas or theories","cn":"以实验（或经验）为依据的；经验主义的","ex":{"en":"empirical evidence/knowledge/research","cn":"实践经验的证明；经验性知识／研究"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"经验主义的;以经验为依据的","en":"Empirical evidence or study relies on practical experience rather than theories.","ex":{"en":"There is no empirical evidence to support his thesis.","cn":"他的论文缺乏实验证据的支持。"}}]},"examples":[{"en":"Such claims need to be tested empirically.","cn":"这类断言需要实践来检验。"},{"en":"empirical evidence/knowledge/research","cn":"实践经验的证明；从实际经验中获得的知识；以实验为基础的研究"}]},"emphasize":{"media":{"uk":"media/uk/emphasize__gb_1.mp3","us":"media/us/emphasize__us_1.mp3"},"oxford":{"phon":"ˈemfəsaɪz","pos":"verb","senses":[{"en":"to give special importance to something","cn":"强调；重视；着重","ex":{"en":"His speech emphasized the importance of attracting industry to the town.","cn":"他的发言强调了将工业吸引到这个城镇的重要性。"}},{"en":"to make something easier to notice","cn":"使突出；使明显","ex":{"en":"She swept her hair back from her face to emphasize her high cheekbones.","cn":"她把头发朝脸后拢，使高高的颧骨显得更为突出。"}},{"en":"to give extra force to a word or phrase when you are speaking, especially to show that it is important","cn":"重读，强调（词或短语）；加强…的语气","ex":{"en":"‘Let nothing… nothing,’ he emphasized the word, ‘tempt you.’","cn":"“不要让任何东西…任何东西，”他强调说，“诱惑你。”"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"强调;重视","en":"To emphasize something means to indicate that it is particularly important or true, or to draw special attention to it.","ex":{"en":"But it's also been emphasized that no major policy changes can be expected to come out of the meeting","cn":"但是也已经强调过，此次会议预计不会带来重大政策转变。"}}]},"examples":[{"en":"She swept her hair back from her face to emphasize her high cheekbones.","cn":"她把头发朝脸后拢时，高高的颧骨显得更为突出。"},{"en":"She emphasized that their plan would mean sacrifices and hard work.","cn":"她强调说他们的计划意味着牺牲和辛勤工作。"}]},"embarrassing":{"oxford":{"phon":"ɪmˈbærəsɪŋ","pos":"adjective","senses":[{"en":"making you feel shy, uncomfortable or ashamed","cn":"使人害羞的（或难堪的、惭愧的）","ex":{"en":"an embarrassing moment/situation","cn":"令人难堪的时刻／处境"}},{"en":"causing somebody to look stupid, dishonest, etc.","cn":"使显得愚蠢的（或不诚实的等）","ex":{"en":"This EU ruling puts Britain in a very embarrassing position.","cn":"欧盟的这一裁决让英国陷入了非常尴尬的境地。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人害羞的;让人难堪的;令人尴尬的","en":"Something that is embarrassing makes you feel shy or ashamed.","ex":{"en":"That was an embarrassing situation for me","cn":"那种情形让我难堪。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"惹麻烦的;使难堪的","en":"Something that is embarrassing to a public figure such as a politician or an organization such as a political party causes problems for them.","ex":{"en":"He has put the Bonn government in an embarrassing position","cn":"他将波恩政府置于窘地。"}}]},"media":{"uk":"media/uk/embarrassing__gb_1.mp3","us":"media/us/embarrassing__us_1.mp3"},"examples":[{"en":"It can be embarrassing for children to tell complete strangers about such incidents.","cn":"让孩子们向素不相识的人讲述这样的事情可能是难为了他们。"},{"en":"It was so embarrassing having to sing in public.","cn":"非得在众人面前唱歌太令人难为情了。"}],"base":"embarrass"},"embarrass":{"oxford":{"phon":"ɪmˈbærəs","pos":"verb","senses":[{"en":"to make somebody feel shy, uncomfortable or ashamed, especially in a social situation","cn":"（尤指在社交场合）使窘迫，使尴尬","ex":{"en":"Her questions about my private life embarrassed me.","cn":"她询问我的私生活使我感到很尴尬。"}},{"en":"to cause problems or difficulties for somebody","cn":"使困惑；使为难；使陷入困境","ex":{"en":"The speech was deliberately designed to embarrass the prime minister.","cn":"这个发言是故意为难首相。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使尴尬;使窘迫;使害羞","en":"If something or someone embarrasses you, they make you feel shy or ashamed.","ex":{"en":"His clumsiness embarrassed him","cn":"他因自己的笨拙而感到尴尬。"}},{"pos":"VERB 动词","cn":"使（公众人物、组织等）难堪;给…出难题","en":"If something embarrasses a public figure such as a politician or an organization such as a political party, it causes problems for them.","ex":{"en":"The Republicans are trying to embarrass the president by thwarting his economic program","cn":"共和党人企图通过阻挠总统的经济计划使其难堪。"}}]},"media":{"uk":"media/uk/embarrass__gb_1.mp3","us":"media/us/embarrass__us_1.mp3"},"examples":[{"en":"It embarrassed her to meet strange men in the corridor at night.","cn":"夜里在走廊上遇见陌生男人使她感到很不好意思。"},{"en":"I didn't want to embarrass him by kissing him in front of his friends.","cn":"我并不想当着他的朋友吻他而使他感到难堪。"}]},"emails":{"lemma":"email","media":{"uk":"media/uk/email__gb_1.mp3","us":"media/us/email__us_1.mp3"}},"emerge":{"media":{"uk":"media/uk/emerge__gb_1.mp3","us":"media/us/emerge__us_1.mp3"},"oxford":{"phon":"ɪˈmɜːdʒ","pos":"verb","senses":[{"en":"to move out of or away from something and become possible to see","cn":"出现；露面","g":"[intransitive]","ex":{"en":"The crabs emerge at low tide to look for food.","cn":"螃蟹在退潮时出来寻找食物。"}},{"en":"to become known","cn":"泄露；被人知道","g":"[intransitive, transitive]","ex":{"en":"No new evidence emerged during the investigation.","cn":"调查过程中未发现新证据。"}},{"en":"to start to exist; to appear or become known","cn":"露头；显现；显露","g":"[intransitive]","ex":{"en":"After the elections opposition groups began to emerge.","cn":"选举以后反对派开始露头。"}},{"en":"to survive a difficult situation or experience","cn":"（从困境或苦难经历中）幸存下来，摆脱出来","g":"[intransitive]","ex":{"en":"She emerged from the scandal with her reputation intact.","cn":"丑闻过后她安然无恙，名声丝毫未受影响。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"出现;露出","en":"To emerge means to come out from an enclosed or dark space such as a room or a vehicle, or from a position where you could not be seen.","ex":{"en":"Richard was waiting outside the door as she emerged","cn":"她出现的时候，理查德正在门外等着。"}},{"pos":"VERB 动词","cn":"（从困境或不好的经历中）摆脱出来，熬出来","en":"If you emerge from a difficult or bad experience, you come to the end of it.","ex":{"en":"There is growing evidence that the economy is at last emerging from recession.","cn":"有越来越多的证据表明经济终于开始摆脱萧条。"}},{"pos":"VERB 动词","cn":"（事实或结果）显露，显现，暴露","en":"If a fact or result emerges from a period of thought, discussion, or investigation, it becomes known as a result of it.","ex":{"en":"...the growing corruption that has emerged in the past few years","cn":"过去几年暴露出来的越来越多的腐败现象"}},{"pos":"VERB 动词","cn":"显露;露头;显现","en":"If someone or something emerges as a particular thing, they become recognized as that thing.","ex":{"en":"Mr Shevardnadze emerged as a major figure in the reform movement","cn":"谢瓦尔德纳泽先生逐渐成为改革运动的重要人物。"}},{"pos":"VERB 动词","cn":"（机构、行业等）形成，兴起，出现","en":"When something such as an organization or an industry emerges, it comes into existence.","ex":{"en":"...the new republic that emerged in October 1917.","cn":"1917年10月成立的新共和国"}}]},"examples":[{"en":"He emerged as a key figure in the campaign.","cn":"他已初露头角，成为这次运动的主要人物。"},{"en":"She emerged from the scandal with her reputation intact.","cn":"她在丑闻中安然无恙，名声丝毫未受影响。"}]},"emotional":{"media":{"uk":"media/uk/emotional__gb_1.mp3","us":"media/us/emotional__us_1.mp3"},"oxford":{"phon":"ɪˈməʊʃənl","pos":"adjective","senses":[{"en":"connected with people’s feelings (= with the emotions)","cn":"感情的；情感的；情绪的","g":"[usually before noun]","ex":{"en":"emotional problems/stress","cn":"情绪问题／压力"}},{"en":"causing people to feel strong emotions","cn":"激起感情的；有感染力的；激动人心的","ex":{"en":"emotional language","cn":"有感染力的语言"}},{"en":"showing strong emotions, sometimes in a way that other people think is unnecessary","cn":"情绪激动的；感情冲动的","lab":"sometimes disapproving","ex":{"en":"an emotional response/reaction","cn":"情绪过激的回答／反应"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"情感上的;情绪上的","en":"Emotional means concerned with emotions and feelings.","ex":{"en":"I needed this man's love, and the emotional support he was giving me","cn":"我需要这个男人的爱，以及他在情感上给我的支持。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"激起强烈感情的;激动人心的","en":"An emotional situation or issue is one that causes people to have strong feelings.","ex":{"en":"It's a very emotional issue. How can you advocate selling the ivory from elephants?","cn":"这是个很容易激起公愤的话题。你怎么能够鼓吹贩卖象牙？"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"情绪激动的;（尤指）愤怒的","en":"If someone is or becomes emotional, they show their feelings very openly, especially because they are upset.","ex":{"en":"He is a very emotional man","cn":"他是个很情绪化的人。"}}]},"examples":[{"en":"They have suffered physically and emotionally.","cn":"他们遭受了肉体上和感情上的折磨。"},{"en":"He tends to get emotional on these occasions.","cn":"他在这些场合往往容易感情冲动。"}]},"emissary":{"media":{"uk":"media/uk/emissary__gb_1.mp3","us":"media/us/emissary__us_1.mp3"},"oxford":{"phon":"ˈemɪsəri","pos":"noun","senses":[{"en":"a person who is sent to deliver an official message, especially from one country to another, or to perform a special task","cn":"特使；密使","ex":{"en":"the King’s special emissary","cn":"国王的特使"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"特使;密使","en":"An emissary is a representative sent by one government or leader to another.","ex":{"en":"...the President's special emissary to Hanoi.","cn":"派往河内的总统特使"}}]},"examples":[{"en":"Japan is sending two emissaries to Washington to discuss trade issues.","cn":"日本将派两位特使去华盛顿商讨贸易问题。"}]},"emotion":{"media":{"uk":"media/uk/emotion__gb_1.mp3","us":"media/us/emotion__us_1.mp3"},"oxford":{"phon":"ɪˈməʊʃn","pos":"noun","senses":[{"en":"a strong feeling such as love, fear or anger; the part of a person’s character that consists of feelings","cn":"强烈的感情；激情；情感；情绪","ex":{"en":"to show/express your emotions","cn":"流露／表达情感"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"情感;情绪","en":"An emotion is a feeling such as happiness, love, fear, anger, or hatred, which can be caused by the situation that you are in or the people you are with.","ex":{"en":"Happiness was an emotion that Reynolds was having to relearn","cn":"雷诺兹已经不知道什么是快乐。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（与理性相对的）感性","en":"Emotion is the part of a person's character that consists of their feelings, as opposed to their thoughts.","ex":{"en":"...the split between reason and emotion.","cn":"理性和感性的划分"}}]},"examples":[{"en":"The decision was based on emotion rather than rational thought.","cn":"这个决定不是基于理性的思考而是基于感情作出的。"},{"en":"They expressed mixed emotions at the news.","cn":"他们对这个消息表现出复杂的感情。"}]},"email":{"media":{"uk":"media/uk/email__gb_1.mp3","us":"media/us/email__us_1.mp3"},"oxford":{"phon":"ˈiːmeɪl","pos":"noun","senses":[{"en":"a way of sending messages and data to other people by means of computers connected together in a network","cn":"电子邮件（通信方式）","g":"[uncountable]","lab":"especially North American English","ex":{"en":"I will be on vacation for a week in November, with no access to email.","cn":"我将在 11 月份休假一周，无法查看电子邮件。"}},{"en":"a message sent by email","cn":"电子邮件","g":"[countable, uncountable]","ex":{"en":"Thanks for your email.","cn":"谢谢你的电邮。"}},{"en":"to send a message to somebody by email","cn":"（给…）发电子邮件；电子邮件发送","ex":{"en":"Patrick emailed me yesterday.","cn":"帕特里克昨天给我发电邮了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"电子邮件","en":"E-mail is a system of sending written messages electronically from one computer to another. E-mail is an abbreviation of (缩略=) 'electronic mail'.","ex":{"en":"You can contact us by e-mail","cn":"你可以通过电子邮件和我们联系。"}},{"pos":"VERB 动词","cn":"给…发电子邮件","en":"If you e-mail someone, you send them an e-mail.","ex":{"en":"Jamie e-mailed me to say he couldn't come","cn":"杰米给我发了电子邮件，说他不能来了。"}}]},"examples":[{"en":"I'll email the documents to her.","cn":"我将用电邮把这些文件发送给她。"},{"en":"I'll email her the documents.","cn":"我将用电邮把这些文件发送给她。"}]},"emotionless":{"media":{"uk":"media/uk/emotionless__gb_1.mp3","us":"media/us/emotionless__us_1.mp3"},"oxford":{"phon":"ɪˈməʊʃənləs","pos":"adjective","senses":[{"en":"not showing any emotion","cn":"没有感情的；冷漠的","ex":{"en":"an emotionless voice","cn":"冷漠的声音"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不露情感的;冷漠的","en":"If you describe someone as emotionless, you mean that they do not show any feelings or emotions.","ex":{"en":"He stood emotionless as he heard the judge pass sentence.","cn":"他面无表情地站在那里，听法官宣布判决。"}}]},"examples":[{"en":"an emotionless voice","cn":"冷漠的声音"}]},"emergence":{"media":{"uk":"media/uk/emergence__gb_1.mp3","us":"media/us/emergence__us_1.mp3"},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"出现;兴起","en":"The emergence of something is the process or event of its coming into existence.","ex":{"en":"...the emergence of new scientific ideas.","cn":"新科技思想的兴起"}}]},"examples":[{"en":"the island's emergence from the sea 3 000 years ago * 3 000","cn":"年前这个岛从大海中露出"},{"en":"the island's emergence from the sea 3 000 years ago","cn":""}],"oxford":{"phon":"ɪˈmɜːdʒəns","pos":"noun","senses":[{"en":"the fact of somebody/something moving out of or away from something and becoming possible to see","cn":"出现；浮现","ex":{"en":"the island’s emergence from the sea 3 000 years ago","cn":"岛在 3 000 年前露出海面"}},{"en":"the fact of starting to exist or becoming known for the first time","cn":"露头；显现；显露","ex":{"en":"the emergence of new technologies","cn":"新技术的出现"}}]}},"employee":{"oxford":{"phon":"ɪmˈplɔɪiː","pos":"noun","senses":[{"en":"a person who is paid to work for somebody","cn":"受雇者；雇工；雇员","ex":{"en":"The firm has over 500 employees.","cn":"这家公司有 500 多名雇员。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"雇员;受雇者","en":"An employee is a person who is paid to work for an organization or for another person.","ex":{"en":"He is an employee of Fuji Bank","cn":"他是富士银行的雇员。"}}]},"media":{"uk":"media/uk/employee__gb_1.mp3","us":"media/us/employee__us_1.mp3"},"examples":[{"en":"The firm has over 500 employees.","cn":"这家公司有 500 多名雇员。"},{"en":"employee rights/relations","cn":"雇员权利/关系"}]},"emotions":{"lemma":"emotion","media":{"uk":"media/uk/emotion__gb_1.mp3","us":"media/us/emotion__us_1.mp3"}},"embarrassed":{"media":{"uk":"media/uk/embarrassed__gb_1.mp3","us":"media/us/embarrassed__us_1.mp3"},"oxford":{"phon":"ɪmˈbærəst","pos":"adjective","senses":[{"en":"shy, uncomfortable or ashamed, especially in a social situation","cn":"（尤指在社交场合）窘迫的，尴尬的，害羞的","ex":{"en":"I've never felt so embarrassed in my life!","cn":"我一生中从未感到如此难堪过！"}},{"en":"not having any money; in a difficult financial situation","cn":"拮据的；经济困难的","lab":"informal"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"窘迫的;惭愧的;尴尬的","en":"A person who is embarrassed feels shy, ashamed, or guilty about something.","ex":{"en":"He looked a bit embarrassed.","cn":"他看起来有点尴尬。"}}]},"examples":[{"en":"Some women are too embarrassed to consult their doctor about the problem.","cn":"有些妇女太害羞，不愿就这个问题向医生咨询。"},{"en":"He felt embarrassed at being the centre of attention.","cn":"他因自己成为众人注目的中心而感到很尴尬。"}],"base":"embarrass"},"empire":{"media":{"uk":"media/uk/empire__gb_1.mp3","us":"media/us/empire__us_1.mp3"},"oxford":{"phon":"ˈempaɪə(r)","pos":"noun","senses":[{"en":"a group of countries or states that are controlled by one leader or government","cn":"帝国","ex":{"en":"These invasions almost led to the collapse of the Roman Empire.","cn":"这些入侵几乎导致了罗马帝国的崩溃。"}},{"en":"a group of commercial organizations controlled by one person or company","cn":"大企业；企业集团","ex":{"en":"He has built a huge business empire from humble beginnings.","cn":"他白手起家创建了庞大的商业帝国。"}},{"en":"an area of activity controlled by one person or group","cn":"势力范围；地盘","ex":{"en":"All the bureaucrats jealously guarded their own little empires.","cn":"所有的官僚都小心翼翼地守护着自己的小地盘。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"帝国","en":"An empire is a number of individual nations that are all controlled by the government or ruler of one particular country.","ex":{"en":"...the Roman Empire.","cn":"罗马帝国"}},{"pos":"N-COUNT 可数名词","cn":"企业王国;企业集团","en":"You can refer to a group of companies controlled by one person as an empire .","ex":{"en":"...the big Mondadori publishing empire.","cn":"庞大的蒙达多利出版帝国"}}]},"examples":[{"en":"a business empire","cn":"大型企业集团"},{"en":"the Roman empire","cn":"罗马帝国"}]},"employment":{"media":{"uk":"media/uk/employment__gb_1.mp3","us":"media/us/employment__us_1.mp3"},"oxford":{"phon":"ɪmˈplɔɪmənt","pos":"noun","senses":[{"en":"work, especially when it is done to earn money; the state of being employed","cn":"工作；职业；受雇","g":"[uncountable, countable]","lab":"formal","ex":{"en":"full-time/part-time employment","cn":"全职／兼职工作"}},{"en":"the situation in which people have work","cn":"就业","g":"[uncountable]","ex":{"en":"The government is aiming at full employment.","cn":"政府在力求实现充分就业。"}},{"en":"the act of employing somebody","cn":"雇用","g":"[uncountable]","ex":{"en":"The law prevented the employment of children under ten in the cotton mills.","cn":"法律禁止棉纺厂雇用十岁以下的童工。"}},{"en":"the use of something","cn":"使用；利用","g":"[uncountable]","lab":"formal","ex":{"en":"the employment of artillery in the capture of the town","cn":"在攻城时使用大炮"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"就业;在职","en":"Employment is the fact of having a paid job.","ex":{"en":"She was unable to find employment","cn":"她没能找到工作。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"雇用","en":"Employment is the fact of employing someone.","ex":{"en":"...the employment of children under nine.","cn":"对不满9岁的儿童的雇用"}},{"pos":"N-UNCOUNT 不可数名词","cn":"工作;职业","en":"Employment is the work that is available in a country or area.","ex":{"en":"...economic policies designed to secure full employment.","cn":"旨在确保充分就业的经济政策"}}]},"examples":[{"en":"Changes in farming methods have badly affected employment in the area.","cn":"耕作方法的改变严重影响了这个地区的就业。"},{"en":"The law prevented the employment of children under ten in the cotton mills.","cn":"法律禁止棉纺厂雇用十岁以下的童工。"}]},"emotionally":{"oxford":{"phon":"ɪˈməʊʃənəli","pos":"adverb","senses":[{"en":"in a way that is connected with people's feelings (= with the emotions)","cn":"在感情（或情感、情绪）方面","ex":{"en":"emotionally disturbed children","cn":"情绪异常的孩子"}},{"en":"in a way that causes people to feel strong emotions","cn":"激起感情地；有感染力地；激动人心地","ex":{"en":"an emotionally charged atmosphere","cn":"群情激昂的气氛"}}]},"media":{"uk":"media/uk/emotionally__gb_1.mp3","us":"media/us/emotionally__us_1.mp3"},"examples":[{"en":"They have suffered physically and emotionally.","cn":"他们遭受了肉体上和感情上的折磨。"},{"en":"I try not to become emotionally involved.","cn":"我尽量在感情上不受到影响。"}]},"embark":{"media":{"uk":"media/uk/embark__gb_1.mp3","us":"media/us/embark__us_1.mp3"},"oxford":{"phon":"ɪmˈbɑːk","pos":"verb","senses":[{"en":"to get onto a ship or plane; to put somebody/something onto a ship or plane","cn":"上船（或飞机）；装船（或飞机）","ex":{"en":"We stood on the pier and watched as they embarked.","cn":"我们站在突码头上目送他们登船。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"着手；开始做","en":"If you embark on something new, difficult, or exciting, you start doing it.","ex":{"en":"He's embarking on a new career as a writer","cn":"他即将开始新的职业生涯——当一名作家。"}},{"pos":"VERB 动词","cn":"登(船);上(船)","en":"When someone embarks on a ship, they go on board before the start of a journey.","ex":{"en":"They travelled to Portsmouth, where they embarked on the battle cruiser HMS Renown","cn":"他们行至朴次茅斯，在那里登上了英国皇家海军“声望号”战列巡洋舰。"}}]},"examples":[{"en":"We stood on the pier and watched as they embarked.","cn":"我们站在突码头上目送他们登船。"},{"en":"They embarked the troops by night.","cn":"他们让部队在夜晚之前上了船。"}]},"embellish":{"media":{"uk":"media/uk/embellish__gb_1.mp3","us":"media/us/embellish__us_1.mp3"},"oxford":{"phon":"ɪmˈbelɪʃ","pos":"verb","senses":[{"en":"to make something more beautiful by adding decoration to it","cn":"美化；装饰；布置","ex":{"en":"The huge carved door was embellished with brass door knockers.","cn":"巨大的雕刻门上装饰着黄铜门环。"}},{"en":"to make a story more interesting by adding details that are not always true","cn":"加以渲染（或润饰）；对…添枝加叶","ex":{"en":"His account of his travels was embellished with details of famous people he met.","cn":"他在游记里加油添醋地提到了很多与名人邂逅的细节。"}}]},"examples":[{"en":"a 16th century church with 18th century embellishments","cn":"具有 18 世纪装饰艺术的 16 世纪教堂"},{"en":"Good pasta needs very little embellishment.","cn":"好的意大利面食用不着过多装饰。"}]},"employer":{"media":{"uk":"media/uk/employer__gb_1.mp3","us":"media/us/employer__us_1.mp3"},"oxford":{"phon":"ɪmˈplɔɪə(r)","pos":"noun","senses":[{"en":"a person or company that pays people to work for them","cn":"雇用者；雇主；老板","ex":{"en":"They're very good employers (= they treat the people that work for them well).","cn":"他们是非常好的雇主。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"雇主;雇用者","en":"Your employer is the person or organization that you work for.","ex":{"en":"He had been sent to Rome by his employer","cn":"他已被老板派往罗马。"}}]},"examples":[{"en":"one of the largest employers in the area","cn":"这个地区最大的雇主之一"},{"en":"They're very good employers (= they treat the people that work for them well).","cn":"他们是非常好的雇主。"}]},"emergency":{"oxford":{"phon":"ɪˈmɜːdʒənsi","pos":"noun","senses":[{"en":"a sudden serious and dangerous event or situation that needs immediate action to deal with it","cn":"突发事件；紧急情况","ex":{"en":"This is a medical emergency needing urgent treatment with antibiotics.","cn":"这是一种急症，需要立刻进行抗生素治疗。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"紧急事件;意外事件;（尤指）事故","en":"An emergency is an unexpected and difficult or dangerous situation, especially an accident, which happens suddenly and which requires quick action to deal with it.","ex":{"en":"He deals with emergencies promptly","cn":"他迅速处理突发事件。"}},{"pos":"ADJ 形容词","cn":"紧急情况下的;应急的","en":"An emergency action is one that is done or arranged quickly and not in the normal way, because an emergency has occurred.","ex":{"en":"The Prime Minister has called an emergency meeting of parliament","cn":"首相已召集议会召开紧急会议。"}},{"pos":"ADJ 形容词","cn":"（设备、供应品等）救急用的，应急的","en":"Emergency equipment or supplies are those intended for use in an emergency.","ex":{"en":"The plane is carrying emergency supplies for refugees","cn":"那架飞机正在为难民运送应急物资。"}}]},"media":{"uk":"media/uk/emergency__gb_1.mp3","us":"media/us/emergency__us_1.mp3"},"examples":[{"en":"The government has declared a state of emergency following the earthquake.","cn":"地震发生后政府已宣布进入紧急状态。"},{"en":"I always have some extra cash with me for emergencies.","cn":"我总是随身多带点现金以备急需。"}]},"employees":{"lemma":"employee"},"employers":{"lemma":"employer"},"emerging":{"oxford":{"phon":"ɪˈmɜːdʒɪŋ","pos":"adjective","senses":[{"en":"starting to exist, grow or become known","cn":"开始出现的；新兴的","ex":{"en":"the emerging markets of South Asia","cn":"南亚新兴市场"}}]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdeemerging.mp3","us":"media/ldoce/hwd/ame/4/laademerging.mp3"},"examples":[{"en":"the country’s emerging oil industry","cn":"该国新兴的石油工业"}],"base":"emerge"},"employing":{"lemma":"employ"},"employments":{"lemma":"employment"},"emerged":{"lemma":"emerge"},"emphasizes":{"lemma":"emphasize"},"employed":{"lemma":"employ"},"emissions":{"lemma":"emission"},"embarked":{"lemma":"embark"},"embraces":{"lemma":"embrace"},"embroidered":{"lemma":"embroider"},"embraced":{"lemma":"embrace"},"embryo":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"胚胎","en":"An embryo is an unborn animal or human being in the very early stages of development.","ex":{"en":"The embryo lives in the amniotic cavity.","cn":"胚胎在羊膜腔中发育。"}},{"pos":"ADJ 形容词","cn":"(想法、体系或机构)萌芽阶段的，初期的","en":"An embryo idea, system, or organization is in the very early stages of development, but is expected to grow stronger.","ex":{"en":"They are an embryo party of government","cn":"他们这个政党有望组建政府，但目前还不成熟。"}},{"pos":"PHRASE 短语","cn":"在萌芽期;在初期","en":"Something that is in embryo is at a very early stage of its development.","ex":{"en":"These developments were foreseen in embryo more than a decade ago.","cn":"这些发展早在十多年前的萌芽阶段就已预见到。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a baby that is developing in its mother's body - used especially by doctors","cn":""},{"en":"a baby that is in the very early stage of development inside its mother's body","cn":""},{"en":"an animal or human that has not yet been born, and has just begun to develop","cn":"胚﹐胚胎"}]},"vocab":{"pos":"n","senses":[{"en":"An embryo is an animal in the phase after fertilization but before birth or hatching. Embryos still live in the womb or egg."}]},"collocations":{"phrases":["ADJ. developing | early the cells of an early embryo | human, frog, etc.","VERB + EMBRYO implant Two or three embryos are implanted into the woman's body.","EMBRYO + VERB develop"]},"media":{"uk":"media/ldoce/hwd/bre/7/embryo0205.mp3","us":"media/ldoce/hwd/ame/9/embryo.mp3"},"examples":[{"en":"The idea already existed in embryo in his earlier novels.","cn":"这个想法在他早期的小说中已初见端倪。"},{"en":"an embryo politician (= one who is not yet very experienced)","cn":"尚未成熟的政治家"}],"oxford":{"phon":"ˈembriəʊ","pos":"noun","senses":[{"en":"a young animal or plant in the very early stages of development before birth, or before coming out of its egg or seed, especially a human egg in the first eight weeks after fertilization","cn":"胚；胚胎；（尤指受孕后八周内的）人类胚胎","ex":{"en":"the current debate over cloning human embryos","cn":"当前关于克隆人类胚胎的辩论"}},{"en":"a thing at a very early stage of development","cn":"初期形态；萌芽；雏形","ex":{"en":"the embryo of an idea","cn":"一种想法的雏形"}}]}},"emaciated":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（因疾病或饥饿而）消瘦的，骨瘦如柴的","en":"A person or animal that is emaciated is extremely thin and weak because of illness or lack of food.","ex":{"en":"...horrific television pictures of emaciated prisoners.","cn":"电视上骨瘦如柴的囚犯们的恐怖画面"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having little fat on your body","cn":""},{"en":"thin in an attractive way","cn":""},{"en":"thin in an attractive and graceful way – used especially about parts of the body, and used especially about women","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Someone who is dangerously skinny and skeletal-looking can be described as emaciated . It's probably how you'd start to look after a few weeks in the wilderness with only berries and bugs for dinner."}]},"collocations":{"phrases":["VERBS be, look | become, grow","ADV. painfully, severely his severely emaciated body"]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdeemaciated.mp3","us":"media/ldoce/hwd/ame/d/emaciated.mp3"},"examples":[{"en":"She was very thin, almost to the point of emaciation.","cn":"她很瘦，几乎到了憔悴的地步。"},{"en":"The prisoners were ill and emaciated.","cn":"囚犯们疾病缠身﹐骨瘦如柴。"}],"oxford":{"phon":"ɪˈmeɪsieɪtɪd","pos":"adjective","senses":[{"en":"thin and weak, usually because of illness or lack of food","cn":"（常指因疾病或缺少食物而）消瘦的，憔悴的，瘦弱的","ex":{"en":"He was thirty, but looked fifty, with pale skin, hopeless eyes and an emaciated body, covered in sores.","cn":"他三十岁了，看上去却是五十岁，皮肤苍白，目光无望，身体瘦弱，浑身疮痍。"}}]}},"emission":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"散发;释放;放射","en":"An emission of something such as gas or radiation is the release of it into the atmosphere.","ex":{"en":"The emission of gases such as carbon dioxide should be stabilised at their present level","cn":"二氧化碳等气体的排放应该稳定在当前水平。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a gas or other substance that is sent into the air","cn":"排放物﹐散发物"},{"en":"the act of sending out light, heat, gas etc 〔","cn":"光﹑热﹑气等的〕散发﹐排放"}]},"vocab":{"pos":"n","senses":[{"en":"An emission is something that's been released or emitted into the world. Car exhaust, burps, and radio broadcasts are all examples of emissions ."}]},"collocations":{"phrases":["ADJ. harmful, noxious, toxic | gaseous | exhaust, vehicle | industrial | atmospheric | acid, carbon, carbon dioxide, lead, sulphur, sulphur ","VERB + EMISSION cut, reduce We must take action to cut vehicle emissions. | control, limit, stabilize","EMISSION + VERB increase | decrease, fall","EMISSION + NOUN levels","PREP. ~s from measures to reduce harmful emissions from traffic"]},"media":{"uk":"media/ldoce/hwd/bre/1/emission0205.mp3","us":"media/ldoce/hwd/ame/9/emission.mp3"},"examples":[{"en":"The government has pledged to clean up industrial emissions.","cn":"政府已保证要清除工业排放物。"},{"en":"the emission of carbon dioxide into the atmosphere","cn":"向大气排放二氧化碳"}],"oxford":{"phon":"ɪˈmɪʃn","pos":"noun","senses":[{"en":"the production or sending out of light, heat, gas, etc.","cn":"（光、热、气等的）发出，射出，排放","g":"[uncountable]","lab":"formal","ex":{"en":"the emission of carbon dioxide into the atmosphere","cn":"向大气排放二氧化碳"}},{"en":"gas, etc. that is sent out into the air","cn":"排放物；散发物","g":"[countable]","lab":"especially British English","ex":{"en":"The government has pledged to clean up industrial emissions.","cn":"政府已保证要清除工业排放物。"}}]}},"embargo":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"禁运;贸易禁令","en":"If one country or group of countries imposes an embargo against another, it forbids trade with that country.","ex":{"en":"The United Nations imposed an arms embargo against the country","cn":"联合国对那个国家实施了武器禁运。"}},{"pos":"VERB 动词","cn":"禁运（货物）","en":"If goods of a particular kind are embargoed, people are not allowed to import them from a particular country or export them to a particular country.","ex":{"en":"The fruit was embargoed","cn":"对水果实施禁运。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an official statement that forbids something, based on a law or a government decision","cn":""},{"en":"official orders forbidding trade or dealings with a particular country, used as a way of punishing them or stopping them from doing something","cn":""},{"en":"an official order forbidding trade in a particular product with a particular country for political or economic reasons","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"An embargo is an order stopping the movement of trade ships into or out of a country. If you can’t get those yummy Swedish fish, perhaps there has been an embargo on trade with Sweden!"}]},"collocations":{"phrases":["ADJ. complete, strict, total | selective | international | economic | arms, oil, trade","VERB + EMBARGO impose, place, put | enforce, tighten | lift The government has agreed to lift the embargo imposed ten years ago. | break, vi","PREP. ~ against the international embargo against the country | ~ on a strict embargo on oil imports"]},"media":{"uk":"media/ldoce/hwd/bre/f/embargo_n0205.mp3","us":"media/ldoce/hwd/ame/3/embargo1.mp3"},"examples":[{"en":"There have been calls to embargo all arms shipments to the region.","cn":"曾有人呼吁禁止所有武器运往这个地区。"},{"en":"an embargo on arms sales to certain countries","cn":"禁止向某些国家出售武器的法令"}],"oxford":{"phon":"ɪmˈbɑːɡəʊ","pos":"noun","senses":[{"en":"an official order that bans trade with another country","cn":"禁止贸易令；禁运","lab":"US English","ex":{"en":"an arms embargo","cn":"武器禁运"}},{"en":"an official ban on any activity","cn":"禁令；禁止","ex":{"en":"There is a complete embargo on taking photographs in court.","cn":"法庭上严禁拍照。"}},{"en":"to officially ban trade with another country","cn":"禁止贸易；禁运","ex":{"en":"There have been calls to embargo all arms shipments to the region.","cn":"曾有人呼吁禁止所有武器运往这个地区。"},"pos":"verb"},{"en":"to officially ban publication of something","cn":"禁止发表；禁止出版","g":"[usually passive]","ex":{"en":"The report is strictly embargoed for publication until Friday.","cn":"这份报告在星期五之前严禁发表。"},"pos":"verb"}]}},"embroider":{"collins":{"senses":[{"pos":"VERB 动词","cn":"在…上刺绣;绣（花）","en":"If something such as clothing or cloth is embroidered with a design, the design is stitched into it.","ex":{"en":"The collar was embroidered with very small red strawberries","cn":"衣领上绣着非常小的红色草莓。"}},{"pos":"VERB 动词","cn":"对（故事、叙述等）添枝加叶渲染","en":"If you embroider a story or account of something, or if you embroider on it, you try to make it more interesting by adding details which may be untrue.","ex":{"en":"He told some lies and sometimes just embroidered the truth","cn":"他说了些谎，有时只是对事实添油加醋了一番。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to decorate cloth by sewing a pattern, picture, or words on it with coloured threads （","cn":"在…上）刺绣"},{"en":"to make a story or report of events more interesting or exciting by adding details that are not true","cn":"对〔故事或报道〕加以渲染"}]},"vocab":{"pos":"v","senses":[{"en":"To embroider means to decorate with needlework. Picture your great grandmother's pillowcases or Hester Prynne's famous scarlet letter \"A\" — both of those objects are probably embroidered ."}]},"collocations":{"phrases":["ADV. beautifully, delicately, exquisitely | heavily, richly a robe of richly embroidered silk","PREP. on She embroidered flowers on the front of the dress. | with She embroidered the dress with flowers."]},"media":{"uk":"media/ldoce/hwd/bre/2/embroider0205.mp3","us":"media/ldoce/hwd/ame/8/embroider.mp3"},"examples":[{"en":"She embroidered flowers on the cushion covers.","cn":"她在这些靠垫套上绣了花。"},{"en":"She embroidered the cushion cover with flowers.","cn":"她在靠垫套上绣了花。"}],"oxford":{"phon":"ɪmˈbrɔɪdə(r)","pos":"verb","senses":[{"en":"to decorate cloth with a pattern of stitches usually using coloured thread","cn":"刺绣","g":"[transitive, intransitive]","ex":{"en":"She embroidered flowers on the cushion covers.","cn":"她在这些靠垫套上绣了花。"}},{"en":"to make a story more interesting by adding details that are not always true","cn":"加以渲染（或润饰）；对…添枝加叶","g":"[transitive]","ex":{"en":"He is inclined to embroider the facts.","cn":"他倾向于粉饰事实。"}}]}},"embassy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（统称）使馆官员;大使馆","en":"An embassy is a group of government officials, headed by an ambassador, who represent their government in a foreign country. The building in which they work is also called an embassy .","ex":{"en":"The American Embassy has already complained","cn":"美国大使馆已经提出了抗议。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"relating to the people who officially represent their government in a foreign country","cn":""},{"en":"a diplomat of the highest rank who is the official representative of their government in a foreign country","cn":""},{"en":"the group of people who are sent to live in a foreign country in order to officially represent their government in that country","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An ambassador, a diplomat who represents her own country in a foreign country, lives and works in an embassy ."}]},"collocations":{"phrases":["ADJ. foreign | British, Chinese, etc.","VERB + EMBASSY open, set up | close They broke off diplomatic relations and closed the embassies in each other's country.","EMBASSY + NOUN building, grounds | official, spokesman/spokeswoman, staff","PREP. at a/the ~ She works at the Malaysian embassy in London. | in a/the ~ a fire in the Spanish embassy | outside a/the ~ a protest outsid"]},"media":{"uk":"media/ldoce/hwd/bre/3/embassy0205.mp3","us":"media/ldoce/hwd/ame/5/embassy.mp3"},"examples":[{"en":"a demonstration outside the Russian Embassy","cn":"在俄罗斯大使馆外的示威游行"},{"en":"to inform the embassy of the situation","cn":"向大使馆报告形势"}],"oxford":{"phon":"ˈembəsi","pos":"noun","senses":[{"en":"a group of officials led by an ambassador who represent their government in a foreign country","cn":"大使馆；（统称）使馆官员","ex":{"en":"embassy officials","cn":"大使馆官员"}},{"en":"the building in which an embassy works","cn":"大使馆（指馆舍）","ex":{"en":"a demonstration outside the Russian Embassy","cn":"在俄罗斯大使馆外的示威游行"}}]}},"emotive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"引起强烈情感的;令人情绪激动的","en":"An emotive situation or issue is likely to make people feel strong emotions.","ex":{"en":"Embryo research is an emotive issue.","cn":"胚胎研究是个容易引起激烈争论的问题。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"causing people to have strong feelings – used especially about experiences, speeches, or subjects that people have strong feelings about","cn":""},{"en":"used about issues or language that make people have strong feelings","cn":""},{"en":"making you feel strong feelings of sadness or sympathy","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something described as emotive shows feeling. If you consider women more emotive than men, you think that women are more comfortable sharing their feelings than men."}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. highly, powerfully, very He raised the highly emotive issue of bullfighting. | rather"]},"media":{"uk":"media/ldoce/hwd/bre/d/emotive0205.mp3","us":"media/ldoce/hwd/ame/6/emotive.mp3"},"examples":[{"en":"Capital punishment is a highly emotive issue.","cn":"死刑是极易引起激烈争论的问题。"},{"en":"emotive language/words","cn":"有感染力的语言/话语"}],"oxford":{"phon":"ɪˈməʊtɪv","pos":"adjective","senses":[{"en":"causing people to feel strong emotions","cn":"激起感情的；有感染力的；激动人心的","ex":{"en":"emotive language/words","cn":"有感染力的语言／话语"}}]}},"emphatic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"强调的;着重的;加强语气的","en":"An emphatic response or statement is one made in a forceful way, because the speaker feels very strongly about what they are saying.","ex":{"en":"His response was immediate and emphatic","cn":"他的反应迅速而强烈。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"措词强烈的;断然的;坚决的","en":"If you are emphatic about something, you use forceful language which shows that you feel very strongly about what you are saying.","ex":{"en":"The rebels are emphatic that this is not a surrender","cn":"叛乱者坚称这并不是投降。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（获胜等）明显的","en":"An emphatic win or victory is one in which the winner has won by a large amount or distance.","ex":{"en":"Yesterday's emphatic victory was their fifth in succession.","cn":"昨天的大胜是他们连续第5场胜利。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"expressing an opinion, idea etc in a clear, strong way to show its importance","cn":"强调的﹔有力的﹔坚决的"},{"en":"a win etc in which one team or player wins by a large amount","cn":"大胜/大败"}]},"vocab":{"pos":"adj","senses":[{"en":"Emphatic means forceful and clear. Nicole's mother was emphatic when she told her not to come home late again."}]},"collocations":{"phrases":["VERBS be | remain","ADV. most, quite, very","PREP. about He was most emphatic about me leaving."]},"media":{"uk":"media/ldoce/hwd/bre/4/emphatic0205.mp3","us":"media/ldoce/hwd/ame/c/emphatic.mp3"},"examples":[{"en":"‘Certainly not,’ he replied emphatically. “","cn":"当然不。”他断然回答道。"},{"en":"He has always emphatically denied the allegations.","cn":"他一直断然否认这些指控。"}],"oxford":{"phon":"ɪmˈfætɪk","pos":"adjective","senses":[{"en":"an emphatic statement, answer, etc. is given with force to show that it is important","cn":"强调的；有力的","ex":{"en":"an emphatic denial/rejection","cn":"断然的否认／拒绝"}},{"en":"making it very clear what you mean by speaking with force","cn":"明确表示的；加强语气的","ex":{"en":"He was emphatic that he could not work with her.","cn":"他强调他不能与她共事。"}},{"en":"an emphatic victory, win, or defeat is one in which one team or player wins by a large amount","cn":"（胜负）明显的，突出的，显著的"}]}},"empathy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同感;同情;共鸣","en":"Empathy is the ability to share another person's feelings and emotions as if they were your own.","ex":{"en":"Having begun my life in a children's home I have great empathy with the little ones.","cn":"由于从小生活在儿童院，我对小家伙们产生了强烈的共鸣。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the ability to understand other people’s feelings and problems","cn":"同情﹔同感﹐共鸣"}]},"vocab":{"pos":"n","senses":[{"en":"Use empathy if you're looking for a noun meaning \"the ability to identify with another's feelings.\""}]},"collocations":{"phrases":["ADJ. deep, great, real | total","VERB + EMPATHY feel, have | demonstrate, show | develop, establish","PREP. ~ between The nurse should try to develop empathy between herself and the patient. | ~ for I felt real empathy for my mother and what ","PHRASES a feeling of empathy, a lack of empathy"]},"media":{"uk":"media/ldoce/hwd/bre/5/empathy0205.mp3","us":"media/ldoce/hwd/ame/9/empathy.mp3"},"examples":[{"en":"the writer's imaginative empathy with his subject","cn":"作者把想像中的感情投入到笔下的人物"},{"en":"The empathy between the two women was obvious.","cn":"显然这两个女人心灵相通。"}],"oxford":{"phon":"ˈempəθi","pos":"noun","senses":[{"en":"the ability to understand another person’s feelings, experience, etc.","cn":"同感；共鸣；同情","ex":{"en":"the writer’s imaginative empathy with his subject","cn":"作者在想象中与笔下的人物情感共鸣"}}]}}});
